#!/usr/bin/env bash
python EE.py --hist "Obj_PU_Corr_DYCR_Resolved_EE_pt" --ymin 10 --ymax 1e6 --output ResolveDYEE_ee_pt --xmin 0 --xmax 1000 --xlabel "Dilepton p_{T} (GeV)" --rmin 0.7 --rmax 1.3 --rebin 5
